def emotion_weight(frame):
    position = (frame - 1) / max(1, END_FRAME - 1)
    for index in range(len(phase_data) - 1):
        left_t, left_v = phase_data[index]
        right_t, right_v = phase_data[index + 1]
        if left_t <= position <= right_t:
            factor = (position - left_t) / max(0.000001, right_t - left_t)
            return left_v + (right_v - left_v) * factor
    return 0.0

speech = {int(frame): float(level) for frame, level in SPEECH_CURVE}
for eye_index, (eye_name, shape_coordinates) in enumerate(COORDINATES.items()):
    eye = bpy.data.objects.get(eye_name)
    if eye is None:
        raise RuntimeError("No se encontró " + eye_name)
    eye_system._eye_ensure_subdivided(eye, 3)
    if len(eye.data.vertices) != len(shape_coordinates):
        raise RuntimeError("Topología incompatible en " + eye_name)
    if not eye.data.shape_keys:
        eye.shape_key_add(name="Basis", from_mix=False)
    blocks = eye.data.shape_keys.key_blocks
    old = blocks.get("Audio_procedural")
    if old:
        eye.shape_key_remove(old)
    shape = eye.shape_key_add(name="Audio_procedural", from_mix=False)
    shape.slider_min = -2.0
    shape.slider_max = 2.0
    for vertex, coordinate in enumerate(shape_coordinates):
        shape.data[vertex].co = coordinate
    eye.data.shape_keys.animation_data_clear()
    eye.animation_data_clear()
    base_location = eye.location.copy()
    base_scale = eye.scale.copy()
    base_rotation = eye.rotation_euler.copy()
    side = 1.0 if eye.matrix_world.translation.x > 0 else -1.0
    eye_amount = 1.0 if eye_index == 0 else 0.86
    previous_speech = 0.0
    for frame in range(1, END_FRAME + 1):
        weight = emotion_weight(frame)
        speech_level = speech.get(frame, 0.0)
        attack = max(0.0, speech_level - previous_speech)
        # Ambos ojos hablan juntos, con una diferencia mínima que evita rigidez.
        wave = math.sin(frame * 1.34 + eye_index * 0.16)
        vertical_pulse = SPEECH_VERTICAL * speech_level * wave * eye_amount
        stretch = wave * speech_level
        for key in blocks:
            if key.name not in ("Basis", "Closed", "Audio_procedural"):
                key.value = 0.0
                key.keyframe_insert(data_path="value", frame=frame)
        shape.value = SHAPE_VALUE * weight * eye_amount
        shape.keyframe_insert(data_path="value", frame=frame)
        closed = blocks.get("Closed")
        if closed:
            closed.value = 0.0
            closed.keyframe_insert(data_path="value", frame=frame)
        eye.location = base_location.copy()
        eye.location.x += side * LATERAL * weight * (1.0 if eye_index == 0 else -0.55)
        eye.location.z += VERTICAL * weight * (1.0 if frame < END_FRAME * 0.60 else 0.65)
        eye.location.z += vertical_pulse
        eye.scale = base_scale.copy()
        eye.scale.x *= 1.0 + (SCALE_X - 1.0) * weight * eye_amount
        eye.scale.z *= 1.0 + (SCALE_Z - 1.0) * weight * eye_amount
        # Squash y stretch de caricatura según intensidad: al subir se alarga;
        # al bajar se ensancha. El ataque añade un pequeño acento volumétrico.
        eye.scale.x *= 1.0 + SPEECH_SCALE_X * speech_level - 0.040 * stretch
        eye.scale.y *= 1.0 - 0.025 * speech_level
        eye.scale.z *= 1.0 + SPEECH_SCALE_Z * speech_level + 0.065 * stretch + 0.025 * attack
        # En duda, el ojo izquierdo es sutilmente menor. La diferencia sigue
        # el peso emocional, por lo que desaparece al regresar a neutral.
        if GENERATED_EMOTION == "duda" and eye_name == "ojo_izquierdo_alfred":
            doubt_size = 1.0 + (DOUBT_LEFT_EYE_SCALE - 1.0) * weight
            eye.scale.x *= doubt_size
            eye.scale.y *= doubt_size
            eye.scale.z *= doubt_size
        eye.rotation_euler = base_rotation.copy()
        # Sigue el signo del ejemplo aprobado `enojado_expresivo`; el acento
        # del habla conserva la misma dirección y nunca invierte la expresión.
        eye.rotation_euler.y += side * ROTATION * weight * eye_amount
        eye.rotation_euler.y += side * ATTACK_ROTATION * attack * eye_amount
        eye.keyframe_insert(data_path="location", frame=frame)
        eye.keyframe_insert(data_path="scale", frame=frame)
        eye.keyframe_insert(data_path="rotation_euler", frame=frame)
        previous_speech = speech_level
    closed = blocks.get("Closed")
    if closed:
        for center in BLINK_CENTERS:
            for frame, value in ((center - 2, 0.0), (center, 1.0), (center + 2, 0.0)):
                closed.value = value
                closed.keyframe_insert(data_path="value", frame=frame)
    for animation in (eye.animation_data, eye.data.shape_keys.animation_data):
        if animation and animation.action:
            for layer in animation.action.layers:
                for strip in layer.strips:
                    for bag in strip.channelbags:
                        for curve in bag.fcurves:
                            for point in curve.keyframe_points:
                                point.interpolation = "BEZIER"
bpy.context.scene.frame_start = 1
bpy.context.scene.frame_end = END_FRAME
bpy.context.scene.render.fps = 24
